    results.push({ json: {
      sourceId: source.id,
      sourceClass: source.sourceClass,
      url: source.url,
      outcome: 'FAILED',
      errorCode: error.code || 'FAILED_CLOSED',
      errorMessage: error.message || 'FAILED_CLOSED',
